//! Small JPEG files made once with libjpeg, kept as hex so that the tests need no encoder. The first two
//! are 16 x 16, gray, baseline, from a pattern of 4 x 4 squares: `SECRET` has the pattern everywhere,
//! `BLANK_TOP` has it only in the lower 8 rows and is white above.

/// The bytes of a hex string.
pub fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

pub const SECRET_HEX: &str = "";

pub const BLANK_TOP_HEX: &str = "";

// 48 x 48 RGB pictures made with libjpeg (Pillow) from a picture of noise on a gradient. The region is the
// samples 5 to 36 in both directions (a square of 32 samples). `REDACTED` has that square set to
// black, `ORIGINAL` has nothing set, and `WRONG_ROWS` has the first 16 rows set to black instead, so
// that half of the region is still there. Quality 75 and 90 with 4:2:0 colour (16 x 16 blocks, the
// default of libjpeg), and quality 75 with 4:4:4 colour.
pub const Q75_420_REDACTED_HEX: &str = "";
pub const Q75_420_ORIGINAL_HEX: &str = "";
pub const Q75_420_WRONG_ROWS_HEX: &str = "";
pub const Q90_420_REDACTED_HEX: &str = "";
pub const Q90_420_ORIGINAL_HEX: &str = "";
pub const Q90_420_WRONG_ROWS_HEX: &str = "";
pub const Q75_444_REDACTED_HEX: &str = "";
